const G={"name": "Wedding Speech Bundle: All Six Speeches (UK)", "slug": "wedding-speech-bundle", "summary": "All six speeches, 30 fill-in templates. Printable PDF plus editable Word file.", "html": "<p>All six wedding speeches in one download, for UK weddings. 30 fill-in templates. Printable PDF (100 pages) plus an editable Word file.</p><p>Speeches included:</p><ul><li>Best man</li><li>Maid of honour</li><li>Father of the bride</li><li>Groom</li><li>Mother of the bride</li><li>Bride (including a version to give together with the groom)</li></ul><p>Each speech has its own full section:</p><ul><li>How to use it, and how long it should be</li><li>The usual UK running order, and what the speech needs to do</li><li>A story worksheet</li><li>How a good speech is built, part by part</li><li>5 fill-in templates: classic, funny, heartfelt, short, and one more</li><li>Opening lines and toasts</li><li>What to leave out, and wording for remembering someone who isn&#x27;t here</li><li>Delivery tips, a final checklist and printable cue cards</li></ul><p>Share it with the whole wedding party, so nobody tells the same story twice.</p><p>Files: 1 PDF (A4, also prints on US Letter) and 1 Word file (.docx). This is a digital download. Nothing will be posted.</p><p>Cheers!</p>", "text": "All six wedding speeches in one download, for UK weddings. 30 fill-in templates. Printable PDF (100 pages) plus an editable Word file.\n\nSpeeches included:\n- Best man\n- Maid of honour\n- Father of the bride\n- Groom\n- Mother of the bride\n- Bride (including a version to give together with the groom)\n\nEach speech has its own full section:\n- How to use it, and how long it should be\n- The usual UK running order, and what the speech needs to do\n- A story worksheet\n- How a good speech is built, part by part\n- 5 fill-in templates: classic, funny, heartfelt, short, and one more\n- Opening lines and toasts\n- What to leave out, and wording for remembering someone who isn't here\n- Delivery tips, a final checklist and printable cue cards\n\nShare it with the whole wedding party, so nobody tells the same story twice.\n\nFiles: 1 PDF (A4, also prints on US Letter) and 1 Word file (.docx). This is a digital download. Nothing will be posted.\n\nCheers!", "imgs": ["bundle-main.jpg", "best-man-inside.jpg", "father-of-the-bride-tmpl.jpg"]};
const sl=ms=>new Promise(r=>setTimeout(r,ms));
const setv=(el,v)=>{Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(el,v);el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))};
const byLabel=l=>[...document.querySelectorAll('input')].find(i=>i.labels?.[0]?.innerText.trim()===l);
setv(byLabel('URL'),G.slug);setv(byLabel('Summary'),G.summary);
const ed=document.querySelector('[contenteditable=true]');ed.focus();document.execCommand('selectAll');
const dt=new DataTransfer();dt.setData('text/html',G.html);dt.setData('text/plain',G.text);ed.dispatchEvent(new ClipboardEvent('paste',{clipboardData:dt,bubbles:true,cancelable:true}));await sl(800);
const base='https://raw.githubusercontent.com/CollingwoodCymbals/cymbalsamples/claude/project-thread-oxai21/etsy-temp/ws/';
const covers=[];for(const n of G.imgs){const b=await fetch(base+n).then(r=>r.blob());covers.push(new File([b],n,{type:'image/jpeg'}))}
const bmp=await createImageBitmap(covers[0]);const c=document.createElement('canvas');c.width=600;c.height=600;c.getContext('2d').drawImage(bmp,0,0,600,600);const tb=await new Promise(r=>c.toBlob(r,'image/jpeg',0.9));const thumb=new File([tb],G.slug+'-thumb.jpg',{type:'image/jpeg'});
const put=(inp,files)=>{const d=new DataTransfer();files.forEach(f=>d.items.add(f));inp.files=d.files;inp.dispatchEvent(new Event('change',{bubbles:true}))};
const fi=[...document.querySelectorAll('input[type=file]')];
put(fi[0],covers);await sl(9000);
const th=[...document.querySelectorAll('input[type=file]')].find(i=>i.labels?.[0]?.innerText.trim()==='Upload');put(th,[thumb]);await sl(5000);
return JSON.stringify({slug:byLabel('URL').value,sum:byLabel('Summary').value.slice(0,30),desc:ed.innerText.slice(0,60),imgs:document.querySelectorAll('img').length})